def verify_topics() -> None:
    assert len(PILLAR1_TOPICS) == 108, f"P1 len={len(PILLAR1_TOPICS)}"
    assert len(PILLAR2_TOPICS) == 108, f"P2 len={len(PILLAR2_TOPICS)}"
    assert len(PILLAR3_TOPICS) == 108, f"P3 len={len(PILLAR3_TOPICS)}"
    all_t = PILLAR1_TOPICS + PILLAR2_TOPICS + PILLAR3_TOPICS
    codes = [x[0] for x in all_t]
    slugs = [x[1] for x in all_t]
    titles = [x[2] for x in all_t]
    assert len(set(codes)) == 324, "Duplicate ep_codes!"
    assert len(set(slugs)) == 324, f"Duplicate slugs! {len(set(slugs))}"
    assert len(set(titles)) == 324, "Duplicate titles!"
    print("Verified 324/324 unique canonical topics across Pillars 1, 2, and 3!")


if __name__ == "__main__":
    verify_topics()
